import { config } from "dotenv";
import { serve } from "@hono/node-server";
import { Hono } from "hono";
import { cors } from "hono/cors";
import { authRouter } from "@/features/auth/routes";

config();

const app = new Hono();

app.use(
  "*",
  cors({
    origin: String(process.env.CORS_ORIGIN ?? "http://localhost:3000").split(","),
    credentials: true,
  })
);

app.route("/auth", authRouter);

const port = Number(process.env.PORT ?? 4000);
serve({ fetch: app.fetch, port });
console.log(`Server running on http://localhost:${port}`);

import { Hono } from "hono";
import { validate } from "@/features/auth/middlewares/validate";
import { auth } from "@/features/auth/middlewares/auth";
import { signupSchema } from "@/features/auth/validation/signup";
import { loginSchema } from "@/features/auth/validation/login";
import { signupHandler } from "@/features/auth/controllers/signupHandler";
import { loginHandler } from "@/features/auth/controllers/loginHandler";
import { refreshHandler } from "@/features/auth/controllers/refreshHandler";
import { logoutHandler } from "@/features/auth/controllers/logoutHandler";
import { meHandler } from "@/features/auth/controllers/meHandler";

const authRouter = new Hono();

authRouter.post("/signup", validate(signupSchema), signupHandler);
authRouter.post("/login", validate(loginSchema), loginHandler);
authRouter.post("/refresh", refreshHandler);
authRouter.post("/logout", auth, logoutHandler);
authRouter.get("/me", auth, meHandler);

export { authRouter };

import type { Context, Next } from "hono";
import type { ZodSchema } from "zod";

export const validate =
  (schema: ZodSchema) =>
  async (c: Context, next: Next) => {
    const body = await c.req.json().catch(() => ({}));
    const result = schema.safeParse(body);

    if (!result.success) {
      return c.json(
        {
          message: "Validation failed",
          errors: result.error.flatten().fieldErrors,
        },
        400
      );
    }

    c.set("validated", result.data);
    return next();
  };

import type { Context, Next } from "hono";
import jwt from "jsonwebtoken";

export const auth = async (c: Context, next: Next) => {
  const authHeader = c.req.header("Authorization");

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return c.json({ message: "Unauthorized" }, 401);
  }

  const token = authHeader.split(" ")[1];

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET!) as {
      userId: string;
    };
    c.set("userId", decoded.userId);
    return next();
  } catch {
    return c.json({ message: "Unauthorized" }, 401);
  }
};

import type { Context } from "hono";
import argon2 from "argon2";
import { prisma } from "@/config";
import {
  generateAccessToken,
  generateRefreshToken,
} from "@/features/auth/utils/tokens";

export const signupHandler = async (c: Context) => {
  const userDetails = c.get("validated");

  const hashedPassword = await argon2.hash(userDetails.password);

  const user = await prisma.user.create({
    data: {
      name: userDetails.name,
      email: userDetails.email,
      password: hashedPassword,
    },
    select: { id: true, email: true, name: true },
  });

  const accessToken = generateAccessToken(String(user.id));
  const refreshToken = generateRefreshToken(String(user.id));

  c.header(
    "Set-Cookie",
    `refreshToken=${refreshToken}; HttpOnly; Max-Age=${7 * 24 * 60 * 60}; SameSite=Lax${
      process.env.NODE_ENV === "production" ? "; Secure" : ""
    }`
  );

  return c.json({ user, accessToken }, 200);
};

import type { Context } from "hono";
import argon2 from "argon2";
import { prisma } from "@/config";
import {
  generateAccessToken,
  generateRefreshToken,
} from "@/features/auth/utils/tokens";

export const loginHandler = async (c: Context) => {
  const credentials = c.get("validated");

  const user = await prisma.user.findUnique({
    where: { email: credentials.email },
    select: { id: true, name: true, email: true, password: true },
  });

  if (!user) {
    return c.json({ message: "User not found" }, 404);
  }

  const valid = await argon2.verify(user.password, credentials.password);
  if (!valid) {
    return c.json({ message: "Invalid credentials" }, 401);
  }

  const accessToken = generateAccessToken(String(user.id));
  const refreshToken = generateRefreshToken(String(user.id));

  c.header(
    "Set-Cookie",
    `refreshToken=${refreshToken}; HttpOnly; Max-Age=${7 * 24 * 60 * 60}; SameSite=Lax${
      process.env.NODE_ENV === "production" ? "; Secure" : ""
    }`
  );

  return c.json(
    { user: { id: user.id, name: user.name, email: user.email }, accessToken },
    200
  );
};

import type { Context } from "hono";
import {
  verifyToken,
  generateAccessToken,
  generateRefreshToken,
} from "@/features/auth/utils/tokens";

export const refreshHandler = async (c: Context) => {
  const cookieHeader = c.req.header("cookie") ?? "";
  const cookies = Object.fromEntries(
    cookieHeader.split("; ").map((pair) => pair.split("="))
  );
  const refreshToken = cookies.refreshToken;

  if (!refreshToken) {
    return c.json({ message: "Unauthorized" }, 401);
  }

  try {
    const decoded = verifyToken(
      refreshToken,
      process.env.JWT_REFRESH_SECRET!
    ) as { userId: string };

    const newAccessToken = generateAccessToken(decoded.userId);
    const newRefreshToken = generateRefreshToken(decoded.userId);

    c.header(
      "Set-Cookie",
      `refreshToken=${newRefreshToken}; HttpOnly; Max-Age=${7 * 24 * 60 * 60}; SameSite=Lax${
        process.env.NODE_ENV === "production" ? "; Secure" : ""
      }`
    );

    return c.json({ accessToken: newAccessToken }, 200);
  } catch {
    return c.json({ message: "Unauthorized" }, 401);
  }
};

import type { Context } from "hono";

export const logoutHandler = async (c: Context) => {
  c.header(
    "Set-Cookie",
    "refreshToken=; HttpOnly; Max-Age=0; SameSite=Lax"
  );

  return c.json({ message: "Logged out successfully" }, 200);
};

import type { Context } from "hono";
import { prisma } from "@/config";

export const meHandler = async (c: Context) => {
  const userId = c.get("userId");

  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: { id: true, email: true, name: true },
  });

  return c.json(user, 200);
};

import { z } from "zod";

export const loginSchema = z.object({
  email: z.string().email(),
  password: z.string().min(8),
});

export type LoginInput = z.infer<typeof loginSchema>;

import { z } from "zod";

export const signupSchema = z.object({
  name: z.string().min(1),
  email: z.string().email(),
  password: z.string().min(8),
});

export type SignupInput = z.infer<typeof signupSchema>;

import jwt from "jsonwebtoken";

export const generateAccessToken = (userId: string) => {
  return jwt.sign({ userId }, process.env.JWT_SECRET!, {
    expiresIn: "15m",
  });
};

export const generateRefreshToken = (userId: string) => {
  return jwt.sign({ userId }, process.env.JWT_REFRESH_SECRET!, {
    expiresIn: "7d",
  });
};

export const verifyToken = (token: string, secret: string) => {
  return jwt.verify(token, secret);
};
